package smp.aeternum.carpet.network;

import com.google.gson.Gson;import net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry;import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;import net.minecraft.server.MinecraftServer;import net.minecraft.server.network.ServerPlayerEntity;import smp.aeternum.carpet.guides.GuideStore;
public final class GuideNetworking {private static final Gson GSON=new Gson();private GuideNetworking(){}
    public static void registerPayloads(){PayloadTypeRegistry.playS2C().register(GuideDataPayload.ID,GuideDataPayload.CODEC);PayloadTypeRegistry.playC2S().register(GuideEditPayload.ID,GuideEditPayload.CODEC);ServerPlayNetworking.registerGlobalReceiver(GuideEditPayload.ID,(p,c)->{if(!c.player().hasPermissionLevel(2))return;String lang=p.lang().isBlank()?"es":p.lang();boolean changed=switch(p.operation()){case "save"->GuideStore.save(lang,p.title(),p.value());case "create"->GuideStore.create(lang,p.title());case "rename"->GuideStore.rename(lang,p.title(),p.value());case "delete"->GuideStore.delete(lang,p.title());case "move_up"->GuideStore.move(lang,p.title(),-1);case "move_down"->GuideStore.move(lang,p.title(),1);case "move_to"->GuideStore.moveTo(lang,p.title(),Integer.parseInt(p.value()));case "reload"->{GuideStore.reload();yield true;}default->false;};if(changed)broadcast(c.server(),lang);});}
    public static void send(ServerPlayerEntity player,boolean open){send(player,open,GuideStore.defaultLang());}
    public static void send(ServerPlayerEntity player,boolean open,String lang){if(ServerPlayNetworking.canSend(player,GuideDataPayload.ID))ServerPlayNetworking.send(player,new GuideDataPayload(GSON.toJson(GuideStore.all(lang)),open,player.hasPermissionLevel(2),lang));}
    public static void broadcast(MinecraftServer server,String lang){for(ServerPlayerEntity p:server.getPlayerManager().getPlayerList())send(p,false,lang);}
}
